mapper.select:
SELECT cl.id, cl.class_name AS className, cl.course_id AS courseId, co.course_name AS courseName, cl.teacher_id AS teacherId, u.real_name AS teacherName, (SELECT COUNT(*) FROM class_student cs WHERE cs.class_id = cl.id) AS studentCount, cl.create_time AS createTime FROM class cl LEFT JOIN course co ON cl.course_id = co.id LEFT JOIN user u ON cl.teacher_id = u.id
AND cl.course_id = #{courseId}
ORDER BY cl.create_time DESC
